chapter(5, 'Folio and payment on the phone', 'Open a guest folio, post a laundry charge and take a UPI payment from the phone.', 'Priya (Cashier)', 'cashier', menu='Cash & Billing > Guests & folios', display='mobile')
step('Priya opens Cash & Billing and then Guests & folios.', 'The cashier works on folios and payments.', target='sel:main', auto=['click:menutop:Cash & Billing', 'click:menuleaf:Guests & folios'], action='click', expect='The folios open.', check="ctx.page==='folios'")
typ('field:Search', 'HCC-1041', 'Type the booking number HCC-1041.', 'The search takes a name, a room, a company or an invoice number.', expect='The folio of Ananya Rao is listed.')
click('btn:Ananya Rao', 'Tap the folio of Ananya Rao.', 'The folio opens with the charges, the receipts and the balance.', expect='The folio opens with the tabs Charges, Receipts and Requests.', check="has('Record payment')")
click('btn:Add charge', 'Tap Add charge.', 'Charges come from the catalogue so price and GST are right.', expect='The Add a service charge sheet opens.', check="has('Post charge')")
pick('field:Item', 'Laundry', 'Choose Laundry, Rs 500 per bag.', 'Laundry carries GST at 18 per cent.', expect='Laundry is selected.')
click('modalbtn:Post charge', 'Tap Post charge.', 'The charge joins the folio with CGST and SGST.', expect='Laundry is on the folio.')
click('btn:Record payment', 'Tap Record payment.', 'A payment before check-out is an advance against the bill.', expect='The payment sheet opens.', check="has('Review')")
click('modalbtn:UPI', 'Tap UPI.', 'The method decides the cashier total the money joins; Cash, UPI, Card, Bank and Split are the choices.', expect='UPI is chosen.')
step('Type the amount 500 and the UPI reference UPI-DEMO-5001.', 'UPI and card payments need a reference so the accountant can match the bank.', target='field:Tender 1 reference', auto=['type:field:Amount|500', 'type:field:Tender 1 reference|UPI-DEMO-5001'], action='type', expect='Amount and reference filled.')
click('modalbtn:Review', 'Tap Review.', 'Review shows the balance after posting.', expect='The receipt summary opens.', check="has('Confirm before posting')")
click('modalbtn:Confirm', 'Tap Confirm with the amount.', 'A repeated tap never makes a second receipt.', expect='The receipt is recorded.', msgText='Receipt recorded once')
